<style lang="scss" scoped>
#anbox {
    cursor: pointer;
    font-size: 13px;
    font-weight: bold;
    width: v-bind("props.sx.w - 5 + 'px'");
    height: 40px;
    display: grid;
    grid-template-columns: 45px 1fr;
    align-items: center;
    border-radius: 8px;
    background-color: v-bind("props.ok.索引 == props.i ? '#ff8fab' : '#28292e'");
    border-style: solid;
    border-width: 1px;
    border-color: #544d55;
    box-shadow: 0 0 5px rgba(0, 0, 0, 0.475);

    &:hover {
        div {
            color: v-bind("props.ok.索引 == props.i ? '#FFFFFF' : hovercolor");
        }

        background-color: v-bind("props.ok.索引 == props.i ? '#ff8fab' : '#FFFFFF'");
    }

    span {
        display: flex;
        justify-content: center;
        padding-left: 20px;


    }

    overflow: hidden;

    &>div:nth-child(3) {
        left: 100px;
        width: 40px;
        height: 30px;
        position: absolute;
        pointer-events: all;
        overflow: hidden;
        &>svg{
            transition: 0.2s;
            transform: translateY(v-bind("props.ok.索引 == props.i ? '-20px' : '0'"))
            
        }
        &:hover{
            &>svg{
                // transform: translateY(0);
                transform: translateY(-20px);
            }
        }
    }
}

span>svg>path {
    fill: aliceblue;
}
